package io.ochre.bridge;
import java.util.*;
import static io.ochre.bridge.ActionSupport.*;

/// Bounded loaded-world geometry and item-tag queries, never chunk generation or pathfinding.
final class WorldQueries {
 private WorldQueries() { }
 static void target(Object c,Map<String,String> result)throws Exception{Object p=player(c),hit=field(c,"hitResult");result.put("world",world(c));if(hit==null){result.put("kind","miss");return;}String kind=call(hit,"getType").toString().toLowerCase(Locale.ROOT);result.put("kind",kind);Object location=call(hit,"getLocation"),eye=call(p,"getEyePosition");for(String axis:List.of("x","y","z"))result.put(axis,field(location,axis).toString());result.put("distance",eye.getClass().getMethod("distanceTo",type(c,"net.minecraft.world.phys.Vec3")).invoke(eye,location).toString());if(kind.equals("block")){Object pos=call(hit,"getBlockPos");for(String axis:List.of("X","Y","Z"))result.put("block_"+axis.toLowerCase(Locale.ROOT),call(pos,"get"+axis).toString());result.put("face",call(hit,"getDirection").toString().toLowerCase(Locale.ROOT));}else if(kind.equals("entity")){Object entity=call(hit,"getEntity");result.put("id",call(entity,"getUUID").toString());result.put("entity_id",call(entity,"getId").toString());result.put("entity_type",id(call(entity,"getType")));result.put("name",call(call(entity,"getName"),"getString").toString());}}
 private static Object box(Object c,double x,double y,double z)throws Exception{Object p=player(c),base=call(p,"getBoundingBox");return base.getClass().getMethod("move",double.class,double.class,double.class).invoke(base,x-number(p,"getX"),y-number(p,"getY"),z-number(p,"getZ"));}
 private static boolean clear(Object c,Object bounds)throws Exception{Object level=field(c,"level"),p=player(c);double minX=((Number)field(bounds,"minX")).doubleValue(),maxX=((Number)field(bounds,"maxX")).doubleValue(),minZ=((Number)field(bounds,"minZ")).doubleValue(),maxZ=((Number)field(bounds,"maxZ")).doubleValue();for(int x=(int)Math.floor(minX);x<=Math.floor(maxX);x++)for(int z=(int)Math.floor(minZ);z<=Math.floor(maxZ);z++){Object pos=type(c,"net.minecraft.core.BlockPos").getConstructor(int.class,int.class,int.class).newInstance(x,0,z);if(!(Boolean)level.getClass().getMethod("hasChunkAt",type(c,"net.minecraft.core.BlockPos")).invoke(level,pos))throw new java.io.IOException("query.chunk.not.loaded");}return (Boolean)level.getClass().getMethod("noCollision",type(c,"net.minecraft.world.entity.Entity"),type(c,"net.minecraft.world.phys.AABB")).invoke(level,p,bounds);}
 static void collision(Object c,Map<String,String> request,Map<String,String> result)throws Exception{Object p=player(c);double x=finite(request,"x"),y=finite(request,"y"),z=finite(request,"z"),dx=x-number(p,"getX"),dy=y-number(p,"getY"),dz=z-number(p,"getZ");double distance=Math.sqrt(dx*dx+dy*dy+dz*dz);if(distance>16)throw new java.io.IOException("query.out.of.range");Object bounds=box(c,x,y,z);boolean body=clear(c,bounds),support=!clear(c,bounds.getClass().getMethod("move",double.class,double.class,double.class).invoke(bounds,0d,-.1d,0d));result.put("clear",Boolean.toString(body));result.put("supported",Boolean.toString(support));result.put("can_stand",Boolean.toString(body&&support));result.put("world",world(c));result.put("distance",Double.toString(distance));if("true".equals(request.get("path"))){boolean path=true;int steps=Math.max(1,(int)Math.ceil(distance*4));for(int i=1;i<=steps;i++){double t=i*1.0/steps;if(!clear(c,box(c,number(p,"getX")+dx*t,number(p,"getY")+dy*t,number(p,"getZ")+dz*t))){path=false;break;}}result.put("path_clear",Boolean.toString(path));}}
 private static double finite(Map<String,String> request,String key)throws Exception{double value=Double.parseDouble(request.getOrDefault(key,"NaN"));if(!Double.isFinite(value)||Math.abs(value)>30_000_000)throw new java.io.IOException("query.coordinate.invalid");return value;}
 static void tags(Object c,Map<String,String> response)throws Exception{Object stack=call(player(c),"getMainHandItem"),item=call(stack,"getItem"),holder=call(item,"builtInRegistryHolder");response.put("item",id(item));List<?> tags;try(var stream=(java.util.stream.Stream<?>)call(holder,"tags")){tags=stream.limit(128).toList();}response.put("count",Integer.toString(tags.size()));for(int i=0;i<tags.size();i++)response.put("tag."+i,call(tags.get(i),"location").toString());}
}
